import os
import json
import sqlite3
import re
import base64
from contextlib import contextmanager

from fastapi import FastAPI, HTTPException
from fastapi.responses import HTMLResponse
from dotenv import load_dotenv
from groq import Groq

load_dotenv()

GROQ_API_KEY = os.environ.get("GROQ_API_KEY", "")
GROQ_MODEL = os.environ.get("GROQ_MODEL", "llama-3.3-70b-versatile")
DB_PATH = os.environ.get("DB_PATH", "countries.db")

app = FastAPI(title="Dunyo Xaritasi API")

groq_client = Groq(api_key=GROQ_API_KEY) if GROQ_API_KEY else None


@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        yield conn
        conn.commit()
    finally:
        conn.close()


def init_db():
    with get_db() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS country_info (
                name TEXT PRIMARY KEY,
                description TEXT NOT NULL,
                events_json TEXT NOT NULL,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            )
        """)


init_db()

SYSTEM_PROMPT = (
    "Siz professional tarixchi va geograf yordamchisiz. Foydalanuvchi bergan davlat "
    "haqida o'zbek tilida ma'lumot tayyorlaysiz. Javobingiz FAQAT quyidagi JSON "
    "formatida bo'lishi kerak, boshqa hech qanday matn, izoh yoki markdown belgisi "
    "qo'shmang:\n"
    '{"description": "davlat haqida 2-3 jumlali qisqacha, qiziqarli ma\'lumot (geografiyasi, '
    'madaniyati yoki o\'ziga xosligi haqida)", '
    '"events": [{"year": "yil yoki davr", "text": "voqeaning qisqa tavsifi (bitta jumla)"}, ...]}\n'
    "events massivida aynan 3 ta eng muhim tarixiy voqea bo'lsin, xronologik tartibda."
)


def extract_json(text: str) -> dict:
    text = text.strip()
    text = re.sub(r"^```(?:json)?", "", text).strip()
    text = re.sub(r"```$", "", text).strip()
    start = text.find("{")
    end = text.rfind("}")
    if start == -1 or end == -1:
        raise ValueError("Javobda JSON topilmadi")
    return json.loads(text[start:end + 1])


@app.get("/api/country/{name}")
def get_country_info(name: str):
    name = name.strip()
    if not name:
        raise HTTPException(400, "Davlat nomi bo'sh bo'lishi mumkin emas")

    with get_db() as conn:
        row = conn.execute(
            "SELECT description, events_json FROM country_info WHERE name = ?", (name,)
        ).fetchone()
        if row:
            return {
                "name": name,
                "description": row["description"],
                "events": json.loads(row["events_json"]),
                "cached": True,
            }

    if not groq_client:
        raise HTTPException(500, "GROQ_API_KEY sozlanmagan")

    try:
        completion = groq_client.chat.completions.create(
            model=GROQ_MODEL,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": f"Davlat: {name}"},
            ],
            temperature=0.6,
            max_tokens=600,
        )
        raw = completion.choices[0].message.content
        parsed = extract_json(raw)
        description = parsed["description"]
        events = parsed["events"]
    except Exception as e:
        raise HTTPException(502, f"AI javobini olishda xatolik: {e}")

    with get_db() as conn:
        conn.execute(
            "INSERT OR REPLACE INTO country_info (name, description, events_json) VALUES (?, ?, ?)",
            (name, description, json.dumps(events, ensure_ascii=False)),
        )

    return {"name": name, "description": description, "events": events, "cached": False}


# ---------------------------------------------------------------------------
# Frontend (single-file bundle): the whole globe UI (HTML/CSS/JS) is embedded
# below as base64, so the entire backend + frontend ships as ONE Python file.
# ---------------------------------------------------------------------------
_INDEX_HTML_B64 = ""
INDEX_HTML = base64.b64decode(_INDEX_HTML_B64).decode("utf-8")


@app.get("/", response_class=HTMLResponse)
def serve_index():
    return HTMLResponse(content=INDEX_HTML)
